<?php
if(!defined('PANIC_ECO_ADMIN') || PANIC_ECO_ADMIN!==true) { http_response_code(403); exit; }
$currency=$_GET['moneda']??'Eryns';if(!is_string($currency) || !in_array($currency,['Eryns','Zen'],true))throw new InvalidArgumentException('Elegí Eryns o Zen.');
$blocks=[];foreach(['Eryns','Zen'] as $coin)$blocks[$coin]=[$ecoRepository->marketTotals($coin),$ecoRepository->marketTotals($coin,true),$ecoRepository->marketSeries($coin)];
$c=$blocks['Eryns'][0];$z=$blocks['Zen'][0];$sellers=$ecoRepository->marketRanking($currency);$buyers=$ecoRepository->marketRanking($currency,true);$detail=$ecoRepository->marketDetail($currency);
panicEcoSentence('Se hicieron '.panicEcoNumber($c['Ventas']).' ventas entre jugadores por '.panicEcoNumber($c['Volumen']).' Eryns. El servidor cobró '.panicEcoNumber($c['Comisiones']).' Eryns de comisión.','Lo vendido pasa de un jugador a otro: no es ganancia del servidor. La comisión desaparece de circulación. Las ventas en Zen se muestran aparte.');
if((float)$c['Ventas']==0 && (float)$z['Ventas']==0)panicEcoEmpty($ecoFilters['tests']);
echo '<div class="eco-market-columns">';foreach($blocks as $coin=>$data){[$current,$previous]=$data;
    echo '<section class="eco-market-column"><header><span class="eco-section-icon">'.panicEcoIcon('coin').'</span><h3>Ventas en '.panicEcoEscape($coin).'</h3></header><div class="eco-market-stats">';
    foreach([['Ventas',$current['Ventas'],'Cantidad de ventas entregadas entre jugadores.'],['Se vendieron entre jugadores',$current['Volumen'],$coin.' que pasaron de un jugador a otro. No es ganancia del servidor.'],['Comisión del mercado',$current['Comisiones'],'El 5% (u 8% si está destacado) que se cobra en cada venta entre jugadores. Desaparece de circulación.'],['Precio promedio',$current['PrecioPromedio'],'Lo vendido dividido por la cantidad de ventas en esta moneda.']] as $stat){echo '<div><span>'.panicEcoEscape($stat[0]).' '.panicEcoHelp($stat[2]).'</span><strong>'.panicEcoNumber($stat[1]).($stat[0]==='Ventas'?'':' <small>'.panicEcoEscape($coin).'</small>').'</strong></div>';}
    echo '</div><p class="eco-note">'.panicEcoNumber($current['Destacadas']).' ventas fueron en puesto destacado y dejaron '.panicEcoNumber($current['ComisionesDestacadas']).' '.panicEcoEscape($coin).' de comisión en total. '.panicEcoHelp('Este importe es toda la comisión de las ventas destacadas; no solo el recargo adicional.').'</p><p class="eco-market-pending">Ventas que el vendedor todavía no cobró: <b>'.panicEcoNumber($current['SinLiquidar']).'</b> '.panicEcoHelp('La venta ya se entregó al comprador, pero el vendedor todavía no recibió su parte.').'</p></section>';
}echo '</div>';
?>
<nav class="eco-subnav" aria-label="Moneda de los vendedores y compradores"><?php foreach(['Eryns','Zen'] as $coin){ ?><a href="<?php echo panicEcoEscape(panicEcoUrl($ecoFilters['query'],['moneda'=>$coin])); ?>" <?php if($coin===$currency)echo 'aria-current="page"'; ?>>Quién vendió y compró · <?php echo $coin; ?></a><?php } ?></nav>
<?php
echo '<div class="eco-rank-grid">';panicEcoRankList('Los 5 que más vendieron · '.$currency,$sellers,'Volumen',$currency);panicEcoRankList('Los 5 que más compraron · '.$currency,$buyers,'Volumen',$currency);echo '</div>';
panicEcoDetailStart('Todas las cifras, compradores, vendedores y últimas ventas');
foreach($blocks as $coin=>$data){[$current,$previous,$chart]=$data;panicEcoChart('Se vendieron entre jugadores y comisión del mercado · '.$coin,'bar',$chart,['Volumen'=>'Se vendieron entre jugadores','Comisiones'=>'Comisión del mercado']);echo '<p class="eco-note">Lo vendido: '.panicEcoEscape(panicEcoComparison($current['Volumen'],$previous['Volumen'],panicEcoPeriodWords($ecoFilters))).'</p>';}
foreach(['Vendedores · '.$currency=>$sellers,'Compradores · '.$currency=>$buyers] as $label=>$rows)panicEcoTable($label,['Cuenta'=>'Jugador','Ventas'=>'Cantidad de ventas','Volumen'=>'Se vendieron entre jugadores · '.$currency],$rows,['numbers'=>['Ventas','Volumen']]);
panicEcoTable('Últimas 500 ventas entregadas · '.$currency,['EntregadaAR'=>'Cuándo se entregó','RequestID'=>'Número de venta','BuyerAccount'=>'Quién compró','SellerAccount'=>'Quién vendió','Precio'=>'Precio · '.$currency,'Comision'=>'Comisión del mercado · '.$currency,'NetoVendedor'=>'Recibió el vendedor · '.$currency,'ComisionPct'=>'Comisión · %','Destacada'=>'Puesto destacado','Liquidada'=>'El vendedor ya cobró'],$detail,['numbers'=>['Precio','Comision','NetoVendedor','ComisionPct'],'dates'=>['EntregadaAR'],'note'=>'La búsqueda muestra las últimas 500 ventas de estas fechas y esta moneda.']);panicEcoDetailEnd();
